//! Strongly typed identifiers.
//!
//! Every id is a `#[repr(transparent)]` newtype over a UUID v7
//! (`Uuid::now_v7()`), generated by [`define_id!`](crate::define_id). Mixing up
//! ids (passing a `ClientId` where a `UserId` is expected) is a compile error.
//!
//! * serde: plain UUID string,
//! * `Display`/`FromStr`: hyphenated UUID,
//! * Postgres (`sqlx` feature): `uuid`, arrays as `uuid[]`.
//!
//! Crates needing ids for their own tables can call
//! `hos_core::define_id! { pub struct FooId; }`.

/// An id string could not be parsed as a UUID.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("invalid {type_name}: {source}")]
pub struct ParseIdError {
    /// Name of the id type, e.g. `"TenantId"`.
    pub type_name: &'static str,
    /// Underlying UUID parse error.
    #[source]
    pub source: uuid::Error,
}

impl ParseIdError {
    /// Creates the error.
    pub fn new(type_name: &'static str, source: uuid::Error) -> Self {
        Self { type_name, source }
    }
}

macro_rules! ids {
    ($($(#[$meta:meta])* $name:ident;)+) => {
        $(crate::define_id! { $(#[$meta])* pub struct $name; })+
    };
}

ids! {
    // ---- platform ------------------------------------------------------
    /// A hosting company using HostingOS (`tenants`).
    TenantId;
    /// A custom domain or subdomain mapped to a tenant (`tenant_domains`).
    TenantDomainId;
    /// A platform operator (`platform_admins`); not tenant scoped.
    PlatformAdminId;
    /// A SaaS plan sold to tenants (`platform_plans`).
    PlatformPlanId;
    /// A tenant's subscription to a platform plan (`tenant_subscriptions`).
    TenantSubscriptionId;

    // ---- identity ------------------------------------------------------
    /// A login account, client or staff (`users`).
    UserId;
    /// A login session (`sessions`).
    SessionId;
    /// An RBAC role (`roles`).
    RoleId;
    /// An API key (`api_keys`).
    ApiKeyId;
    /// An audit log entry (`audit_log`).
    AuditLogId;

    // ---- clients -------------------------------------------------------
    /// A billing customer / company profile (`clients`).
    ClientId;
    /// A contact belonging to a client (`contacts`).
    ContactId;
    /// A client group used for pricing/discounts (`client_groups`).
    ClientGroupId;

    // ---- catalog -------------------------------------------------------
    /// A storefront product group (`product_groups`).
    ProductGroupId;
    /// A sellable product (`products`).
    ProductId;
    /// A product addon (`product_addons`).
    ProductAddonId;
    /// A configurable option group (`config_option_groups`).
    ConfigOptionGroupId;
    /// A configurable option (`config_options`).
    ConfigOptionId;
    /// A coupon / promotion code (`coupons`).
    CouponId;
    /// A tax rule (`tax_rules`).
    TaxRuleId;

    // ---- sales ---------------------------------------------------------
    /// A shopping cart (`carts`).
    CartId;
    /// An order (`orders`).
    OrderId;
    /// A line of an order (`order_items`).
    OrderItemId;
    /// An invoice (`invoices`).
    InvoiceId;
    /// A line of an invoice (`invoice_items`).
    InvoiceItemId;
    /// A payment transaction (`transactions`).
    TransactionId;
    /// A credit balance movement (`credits`).
    CreditId;
    /// A refund (`refunds`).
    RefundId;

    // ---- services ------------------------------------------------------
    /// A configured provider integration (`integrations`).
    IntegrationId;
    /// A provisioned service (`services`).
    ServiceId;
    /// An addon attached to a service (`service_addons`).
    ServiceAddonId;
    /// A virtual machine mapping (`vms`).
    VmId;
    /// An IP address pool (`ip_pools`).
    IpPoolId;
    /// A single IP address in a pool (`ip_addresses`).
    IpAddressId;

    // ---- domains -------------------------------------------------------
    /// A registered/managed domain (`domains`).
    DomainId;
    /// A sellable TLD (`tlds`).
    TldId;
    /// A DNS zone (`dns_zones`).
    DnsZoneId;
    /// A DNS record (`dns_records`).
    DnsRecordId;

    // ---- support -------------------------------------------------------
    /// A support department (`ticket_departments`).
    TicketDepartmentId;
    /// A support ticket (`tickets`).
    TicketId;
    /// A message in a ticket (`ticket_messages`).
    TicketMessageId;
    /// A knowledge base article (`kb_articles`).
    KbArticleId;
    /// An announcement (`announcements`).
    AnnouncementId;

    // ---- content / system ---------------------------------------------
    /// A CMS page (`pages`).
    PageId;
    /// A blog post (`blog_posts`).
    BlogPostId;
    /// A background job (`jobs`).
    JobId;
    /// An email template (`email_templates`).
    EmailTemplateId;
    /// An outgoing webhook endpoint (`webhook_endpoints`).
    WebhookEndpointId;
    /// A received webhook, for idempotency (`webhooks_in`).
    WebhookInId;
    /// A user notification (`notifications`).
    NotificationId;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_v7_and_ordered() {
        let a = TenantId::new();
        let b = TenantId::new();
        assert_eq!(a.as_uuid().get_version_num(), 7);
        assert!(a <= b);
        assert!(a.created_at().is_some());
    }

    #[test]
    fn display_fromstr_roundtrip() {
        let id = InvoiceId::new();
        let parsed: InvoiceId = id.to_string().parse().unwrap();
        assert_eq!(id, parsed);
        let err = "nope".parse::<InvoiceId>().unwrap_err();
        assert_eq!(err.type_name, "InvoiceId");
    }

    #[test]
    fn serde_is_transparent() {
        let id = ServiceId::new();
        let json = serde_json::to_string(&id).unwrap();
        assert_eq!(json, format!("\"{id}\""));
        let back: ServiceId = serde_json::from_str(&json).unwrap();
        assert_eq!(back, id);
    }

    #[test]
    fn debug_includes_type_name() {
        let id = ClientId::from_uuid(uuid::Uuid::nil());
        assert_eq!(
            format!("{id:?}"),
            "ClientId(00000000-0000-0000-0000-000000000000)"
        );
    }
}
